INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Run Your Week in Half the Time: The Claude and Assistant Playbook [ONLINE]', 'Denver AI for Small Business & Founders', 'Women in Business', 'In this session we''ll put together a complete weekly system where Claude drafts, an assistant sends and the owner decides, so the week no', 'In this session we''ll put together a complete weekly system where Claude drafts, an assistant sends and the owner decides, so the week no longer runs through one person. We will walk through a real owner''s week before and after, including the 15-minute weekly review that keeps it running. **What we''ll cover:** • The full weekly system: what Claude does, what an assistant does, what only you do • Planning, inbox, follow-ups and written procedures working as one routine • A real owner''s week, More info: https://www.meetup.com/denver-ai-for-small-business-founders/events/316698098/', '2026-10-12T14:00:00-06:00', 'Online event', 'Online event', 'Denver', 'CO', '', 39.7, -105.08, 'Denver AI for Small Business & Founders', 23, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/denver-ai-for-small-business-founders/events/316698098/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How We Got 256 Customers in 90 Days: The AI Sales Funnel, Step by Step [ONLINE]', 'Denver AI for Small Business & Founders', 'Women in Business', '**(PLEASE READ THE NOTE AT THE BOTTOM BEFORE YOU RSVP)** A step-by-step walkthrough of the AI sales funnel that brought in 256 paying', '**(PLEASE READ THE NOTE AT THE BOTTOM BEFORE YOU RSVP)** A step-by-step walkthrough of the AI sales funnel that brought in 256 paying customers in 90 days, built for solopreneurs and small business owners. The actual system, the actual numbers, and the AI tools behind each step. Most owners win clients the slow way: referrals, cold outreach and chasing leads who went quiet. That works until things get busy, and then new business stops. An automated funnel solves that. AI now drafts the pages, More info: https://www.meetup.com/denver-ai-for-small-business-founders/events/316887213/', '2026-10-14T13:00:00-06:00', 'Online event', 'Online event', 'Denver', 'CO', '', 39.7, -105.08, 'Denver AI for Small Business & Founders', 63, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/denver-ai-for-small-business-founders/events/316887213/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Hire the Top 1% Remote Assistant: Find, Test and Train Them with Claude [ONLINE]', 'Denver AI for Small Business & Founders', 'Women in Business', 'In this session we''ll walk through how to find, test and hire a top 1% remote assistant who already knows how to use AI, and how Claude', 'In this session we''ll walk through how to find, test and hire a top 1% remote assistant who already knows how to use AI, and how Claude writes the job post, the test task and the training docs for you. Most owners hire their first assistant in a rush, pick the wrong person and end up doing the work twice. A clear role, a short paid test and written training change the outcome. **What we''ll cover:** • Which tasks to hand off first, and the one role that covers them • Where the best AI-savvy More info: https://www.meetup.com/denver-ai-for-small-business-founders/events/316836729/', '2026-10-21T13:00:00-06:00', 'Online event', 'Online event', 'Denver', 'CO', '', 39.7, -105.08, 'Denver AI for Small Business & Founders', 6, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/denver-ai-for-small-business-founders/events/316836729/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Hire Your First Remote Assistant and Manage Them with Claude [ONLINE]', 'Denver AI for Small Business & Founders', 'Women in Business', 'In this session we''ll plan a first remote assistant hire from start to finish: what to hand over, where to find good people, how to test', 'In this session we''ll plan a first remote assistant hire from start to finish: what to hand over, where to find good people, how to test them, and how Claude writes the training material. A remote assistant is often the fastest way for an owner to get time back. The hire goes well when the role and the handover are clear before day one. **What we''ll cover:** • Deciding which tasks an assistant should own first • Writing the job post and a short paid test task with Claude • Training material and More info: https://www.meetup.com/denver-ai-for-small-business-founders/events/316859877/', '2026-10-22T12:00:00-06:00', 'Online event', 'Online event', 'Denver', 'CO', '', 39.7, -105.08, 'Denver AI for Small Business & Founders', 6, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/denver-ai-for-small-business-founders/events/316859877/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
