INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Online Home Buying 101', 'Denver Real Estate: Home Buyers & 1st Time Investors Meetup', 'Real Estate', 'You''ll learn about the home buying process, take a look at a rent vs buy analysis, and learn some basic investment strategies. Whether it', 'You''ll learn about the home buying process, take a look at a rent vs buy analysis, and learn some basic investment strategies. Whether it makes sense for you to buy now or buy later, come get the information you need to make an educated decision and an understanding of how the whole process works. Don''t let not knowing how it works discourage you from making a positive, long-term financial decision for yourself! Register Here: More info: https://www.meetup.com/denver-real-estate-home-buyers-1st-time-investors-meetup/events/311364030/', '2026-11-18T17:30:00-07:00', 'Online event', 'Online event', 'Denver', 'CO', '', 39.77, -105.01, 'Denver Real Estate: Home Buyers & 1st Time Investors Meetup', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/denver-real-estate-home-buyers-1st-time-investors-meetup/events/311364030/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
