INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('YOU HAD ME AT DIM SUM (SGV)', 'Dimsumx – Los Angeles', 'Founders & Startups', '**YOU HAD ME AT DIM SUM** *A singles social by DIMSUMX* **You have a type. But have you tried the whole menu?** Maybe you’re the chicken', '**YOU HAD ME AT DIM SUM** *A singles social by DIMSUMX* **You have a type. But have you tried the whole menu?** Maybe you’re the chicken feet: a little intimidating at first, soft underneath. Maybe you’re the beef stomach: complicated, takes a little figuring out. Or the custard bun: sweet, warm, and occasionally a hot mess. Whatever your filling, there’s a seat for you. **Forget Hinge and Bumble for an afternoon.** You’ve read enough bios. Come find out how someone orders dim sum. Join us for More info: https://www.meetup.com/dimsumx-los-angeles/events/316729962/', '2026-10-10T13:00:00-07:00', 'Big Ma''s Kitchen', '7808 Garvey Ave, Rosemead, CA 91770, USA', 'Rosemead', 'CA', '91770', 34.062567269109, -118.09915152021, 'Dimsumx – Los Angeles', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/dimsumx-los-angeles/events/316729962/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Meditation & Discussion', 'Angel City Zen Center', 'General Networking', 'The class will consist of thirty minutes of Zen meditation followed by discussion. There will be instructions, so beginners are encouraged', 'The class will consist of thirty minutes of Zen meditation followed by discussion. There will be instructions, so beginners are encouraged to join. Zen meditation is simple and the technique can be learned in just a few minutes, though it may take years to refine it. Monday night sits are currently being held both in-person indoors and on Zoom. Please email us at **info@aczc.org** for the Zoom link. (Please don''t let the lack of RSVPs discourage you from coming. We are a long established group. More info: https://www.meetup.com/dogen-sangha-los-angeles-zen-meditation/events/316673945/', '2026-10-12T19:30:00-07:00', 'Angel City Zen Center', '2526 Kent Street', 'Los Angeles', 'CA', '', 34.08, -118.26, 'Angel City Zen Center', 2, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/dogen-sangha-los-angeles-zen-meditation/events/316673945/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Meditation and Koan Discussion (Zoom Only)', 'Angel City Zen Center', 'General Networking', 'Get down and nerdy with ACZC''s take on koan study: half hour sit, followed by tea and a discussion of a koan from Nishijima''s translation', 'Get down and nerdy with ACZC''s take on koan study: half hour sit, followed by tea and a discussion of a koan from Nishijima''s translation of Dogen''s Shinji Shobogenjo. There no right or wrong answers here! Just freewheeling group discussions that rarely go where you''d predict. If you don''t know what koans are, don''t worry! We''re not exactly sure still either. Come help us try and find out. Please note that Wednesday koan nights are on Zoom *only*. **Please email us at info@aczc.org for the Zoom More info: https://www.meetup.com/dogen-sangha-los-angeles-zen-meditation/events/316704281/', '2026-10-14T19:30:00-07:00', 'Online event', 'Online event', 'Los Angeles', 'CA', '', 34.08, -118.26, 'Angel City Zen Center', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/dogen-sangha-los-angeles-zen-meditation/events/316704281/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Meditation and Discussion', 'Angel City Zen Center', 'General Networking', 'The class will consist of two thirty minute sessions of Zen meditation, with a ten minute walking meditation in between, followed by a talk', 'The class will consist of two thirty minute sessions of Zen meditation, with a ten minute walking meditation in between, followed by a talk and discussion. There will be instructions, so beginners are encouraged to join. Zen meditation is simple and the technique can be learned in just a few minutes, though it may take years to refine it. No experience required. Beginners welcome! Saturday events are currently being held both in-person indoors and on Zoom. **Please email us at info@aczc.org for More info: https://www.meetup.com/dogen-sangha-los-angeles-zen-meditation/events/316737602/', '2026-10-17T10:00:00-07:00', 'Angel City Zen Center', '2526 Kent Street', 'Los Angeles', 'CA', '', 34.08, -118.26, 'Angel City Zen Center', 3, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/dogen-sangha-los-angeles-zen-meditation/events/316737602/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
